def validate(inp):
    lines = inp.strip().split("\n")
    if len(lines) != 2:
        return False
    head = lines[0].split()
    if len(head) != 2:
        return False
    n, k = int(head[0]), int(head[1])
    r = [int(x) for x in lines[1].split()]
    if not (1 <= n <= 8 and 2 <= k <= 10):
        return False
    if len(r) != n:
        return False
    return all(1 <= x <= 5 for x in r)

def ref(inp):
    lines = inp.strip().split("\n")
    n, k = map(int, lines[0].split())
    r = [int(x) for x in lines[1].split()]
    out = []
    # product over ranges 1..R_i yields sequences in ascending lexicographic order
    ranges = [range(1, r[i] + 1) for i in range(n)]
    for seq in product(*ranges):
        if sum(seq) % k == 0:
            out.append(" ".join(map(str, seq)))
